CREATE DATABASE security_assets CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci; USE security_assets;
CREATE TABLE settings(`key` varchar(64) PRIMARY KEY,value varchar(255) NOT NULL);INSERT INTO settings VALUES('eval_min','1'),('eval_max','3');
CREATE TABLE users(id bigint unsigned AUTO_INCREMENT PRIMARY KEY,username varchar(64) UNIQUE NOT NULL,password_hash varchar(255) NOT NULL,display_name varchar(100) NOT NULL,role enum('admin','oper','user') NOT NULL,enabled tinyint NOT NULL DEFAULT 1,last_login_at datetime,last_seen_at datetime,last_logout_at datetime,created_at datetime DEFAULT current_timestamp);
CREATE TABLE locations(id bigint unsigned AUTO_INCREMENT PRIMARY KEY,name varchar(150) UNIQUE NOT NULL,enabled tinyint NOT NULL DEFAULT 1,display_order int NOT NULL DEFAULT 0);
CREATE TABLE purposes(id bigint unsigned AUTO_INCREMENT PRIMARY KEY,name varchar(100) UNIQUE NOT NULL,asset_prefix varchar(32) UNIQUE NOT NULL,next_sequence int unsigned NOT NULL DEFAULT 1,server_target tinyint NOT NULL DEFAULT 0,enabled tinyint NOT NULL DEFAULT 1);INSERT INTO purposes(name,asset_prefix,server_target) VALUES('서버','NA-S',1),('네트워크','NA-N',1),('도구','NA-T',1),('PC','NA-P',0),('소프트웨어','NA-SW',0);
CREATE TABLE assets(id bigint unsigned AUTO_INCREMENT PRIMARY KEY,asset_no varchar(40) UNIQUE NOT NULL,asset_type enum('hardware','software') NOT NULL,asset_class enum('normal','sample') NOT NULL DEFAULT 'normal',asset_name varchar(150) NOT NULL,purpose_id bigint unsigned NOT NULL,assignee varchar(100) NOT NULL,location varchar(150),manufacturer varchar(100),model_name varchar(150),serial_no varchar(150),purchase_date date,quantity int unsigned,mac_address varchar(64),os_name varchar(150),ip_address varchar(64),port_info varchar(255),monthly_check tinyint NOT NULL DEFAULT 0,eval_c smallint,eval_i smallint,eval_a smallint,eval_r smallint,enabled tinyint NOT NULL DEFAULT 1,deleted_at datetime,created_at datetime DEFAULT current_timestamp,updated_at datetime DEFAULT current_timestamp ON UPDATE current_timestamp,FOREIGN KEY(purpose_id) REFERENCES purposes(id));
CREATE TABLE software_licenses(id bigint unsigned AUTO_INCREMENT PRIMARY KEY,asset_id bigint unsigned NOT NULL,license_code varchar(255) NOT NULL,note varchar(255),enabled tinyint NOT NULL DEFAULT 1,created_at datetime DEFAULT current_timestamp,UNIQUE(asset_id,license_code),FOREIGN KEY(asset_id) REFERENCES assets(id) ON DELETE CASCADE);
CREATE TABLE software_requests(id bigint unsigned AUTO_INCREMENT PRIMARY KEY,asset_id bigint unsigned NOT NULL,requester_user_id bigint unsigned NOT NULL,purpose_text varchar(500) NOT NULL,start_date date,due_date date,status enum('pending','approved','rejected','issued','returned','cancelled') NOT NULL DEFAULT 'pending',approver_user_id bigint unsigned,approved_at datetime,reject_reason varchar(500),created_at datetime DEFAULT current_timestamp,FOREIGN KEY(asset_id) REFERENCES assets(id),FOREIGN KEY(requester_user_id) REFERENCES users(id),FOREIGN KEY(approver_user_id) REFERENCES users(id));
CREATE TABLE software_license_assignments(id bigint unsigned AUTO_INCREMENT PRIMARY KEY,request_id bigint unsigned,asset_id bigint unsigned NOT NULL,license_id bigint unsigned,user_name varchar(100) NOT NULL,assigned_date date NOT NULL,returned_date date,memo varchar(255),actor_user_id bigint unsigned,created_at datetime DEFAULT current_timestamp,FOREIGN KEY(request_id) REFERENCES software_requests(id),FOREIGN KEY(asset_id) REFERENCES assets(id),FOREIGN KEY(license_id) REFERENCES software_licenses(id),FOREIGN KEY(actor_user_id) REFERENCES users(id));
CREATE TABLE sample_specs(id bigint unsigned AUTO_INCREMENT PRIMARY KEY,asset_id bigint unsigned NOT NULL,spec_type enum('CPU','MEM','DISK','NIC','PSU','ETC') NOT NULL,model_name varchar(200) NOT NULL,quantity int unsigned NOT NULL DEFAULT 1,FOREIGN KEY(asset_id) REFERENCES assets(id) ON DELETE CASCADE);
CREATE TABLE software_transactions(id bigint unsigned AUTO_INCREMENT PRIMARY KEY,asset_id bigint unsigned NOT NULL,user_name varchar(100) NOT NULL,quantity int unsigned NOT NULL,assigned_date date NOT NULL,returned_date date,memo varchar(255),created_at datetime DEFAULT current_timestamp,FOREIGN KEY(asset_id) REFERENCES assets(id));
CREATE TABLE sample_requests(id bigint unsigned AUTO_INCREMENT PRIMARY KEY,asset_id bigint unsigned NOT NULL,requester_user_id bigint unsigned NOT NULL,purpose_text varchar(500) NOT NULL,start_date date NOT NULL,due_date date NOT NULL,status enum('pending','approved','rejected','issued','returned','cancelled') NOT NULL DEFAULT 'pending',approver_user_id bigint unsigned,approved_at datetime,issued_at datetime,returned_at datetime,reject_reason varchar(500),memo varchar(500),created_at datetime DEFAULT current_timestamp,FOREIGN KEY(asset_id) REFERENCES assets(id),FOREIGN KEY(requester_user_id) REFERENCES users(id),FOREIGN KEY(approver_user_id) REFERENCES users(id));
CREATE TABLE layouts(id bigint unsigned AUTO_INCREMENT PRIMARY KEY,kind enum('rack','space') NOT NULL,name varchar(100) UNIQUE NOT NULL,description varchar(255),display_order int NOT NULL DEFAULT 0);
CREATE TABLE layout_assets(id bigint unsigned AUTO_INCREMENT PRIMARY KEY,layout_id bigint unsigned NOT NULL,asset_id bigint unsigned NOT NULL UNIQUE,display_order int NOT NULL DEFAULT 0,FOREIGN KEY(layout_id) REFERENCES layouts(id) ON DELETE CASCADE,FOREIGN KEY(asset_id) REFERENCES assets(id));
CREATE TABLE audit_logs(id bigint unsigned AUTO_INCREMENT PRIMARY KEY,actor_user_id bigint unsigned,action varchar(40) NOT NULL,entity_type varchar(40) NOT NULL,entity_id bigint unsigned,entity_name varchar(150),asset_no varchar(40),before_data longtext,after_data longtext,reason varchar(500),created_at datetime DEFAULT current_timestamp,FOREIGN KEY(actor_user_id) REFERENCES users(id));